SELECT t.id AS id, t.task_name AS taskName, t.execute_type AS executeType, COALESCE(JSON_LENGTH(JSON_EXTRACT(t.rule_scope, '$.ruleIds')), 0) AS ruleCount, t.total_host_count AS hostCount, (SELECT ROUND(AVG(s.compliance_rate), 2) FROM baseline_summary s WHERE s.task_id = t.id) AS avgPassRate, t.status AS status, t.create_time AS createTime FROM baseline_task t
t.status = #{status}
ORDER BY t.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM baseline_task t


        t.status = #{status}
